const GLOBAL_TOP_MODAL_STACK_KEY = Symbol.for('Ks.topModalIdStack');
const GLOBAL_SCROLL_LOCK_COUNT_KEY = Symbol.for('Ks.lockScrollCount');

declare global {
  interface Window {
    [GLOBAL_TOP_MODAL_STACK_KEY]?: number[];
    [GLOBAL_SCROLL_LOCK_COUNT_KEY]: number;
  }
}

if (!window[GLOBAL_TOP_MODAL_STACK_KEY]) {
  window[GLOBAL_TOP_MODAL_STACK_KEY] = [];
}
const stack = window[GLOBAL_TOP_MODAL_STACK_KEY];

export const topModalIdStack = {
  last() {
    return stack[stack.length - 1];
  },
  remove(id: number) {
    const index = stack.indexOf(id);
    if (index !== -1) {
      stack.splice(index, 1);
    }
  },
  push(id: number) {
    if (!stack.includes(id)) {
      stack.push(id);
    }
  },
};

let modalUUID = 0;
export const getOverlayUUID = () => modalUUID++;

if (typeof window[GLOBAL_SCROLL_LOCK_COUNT_KEY] !== 'number') {
  window[GLOBAL_SCROLL_LOCK_COUNT_KEY] = 0;
}
export const globalScrollLock = {
  acquire() {
    if (window[GLOBAL_SCROLL_LOCK_COUNT_KEY]++ === 0) {
      document.body.classList.add('ks-overlay-body-scroll-locked');
    }
  },
  release() {
    if (--window[GLOBAL_SCROLL_LOCK_COUNT_KEY] === 0) {
      document.body.classList.remove('ks-overlay-body-scroll-locked');
    }
  },
};
