import { Component, Host, Prop, h, Event, type ComponentInterface, Watch, type EventEmitter } from '@stencil/core';
import { getOverlayUUID, globalScrollLock, topModalIdStack } from './utils';
import {
  allocateFallbackZIndex,
  KS_TOP_LAYER_SURFACE_ATTR,
  supportsPopoverApi,
  whenNotReconnected,
} from '@src/shared/dom';

const prefix = 'overlay';
const topLayerSurfaceAttrs = { [KS_TOP_LAYER_SURFACE_ATTR]: '' };

// FIXME [issue#1] currently click event can bubbles up across KsOverlay, creating issues.
// [issue#1] also affects KsTable. The workaround in KsTable can be removed once the issue is gone.

/**
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-overlay',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsOverlay implements ComponentInterface {
  private el?: HTMLDialogElement | HTMLDivElement;
  private modalId = getOverlayUUID();
  private cleanupKeydownListener?: () => void;
  private hasScrollLock = false;
  private isPresented = false;

  private setBaseRef = (el?: HTMLDialogElement | HTMLDivElement) => {
    if (this.el !== el) {
      this.isPresented = false;
    }
    this.el = el;
  };

  /** Controls whether the overlay is open (visible) or closed (hidden). */
  @Prop() open = false;

  /** Overlay hosting mode. `modal` uses a dialog host and `modeless` uses a manual popover/fallback host. */
  @Prop() mode: 'modal' | 'modeless' = 'modal';

  /** Whether the overlay should capture the Escape key when top-most. */
  @Prop() captureEscape?: boolean;
  /** Whether the overlay should request close on Escape when top-most. */
  @Prop() closeByEscape?: boolean;
  /** Override z-index for fallback/non-top-layer hosts. */
  @Prop() zIndex?: number;

  /**
   * @deprecated Only for compatibility with non-Keystone overlay components.
   * Disable the [top layer](https://developer.mozilla.org/en-US/docs/Glossary/Top_layer) API with `position: fixed`.
   */
  @Prop() deprecatedDisableTopLayer = false;

  /** Emits when the overlay requests close because Escape was pressed. */
  @Event() ksRequestClose!: EventEmitter<'escape'>;

  private get shouldLockScroll() {
    return this.mode === 'modal';
  }

  private get shouldUseNativePopoverApi() {
    return this.mode === 'modeless' && !this.deprecatedDisableTopLayer && supportsPopoverApi(this.el);
  }

  private get shouldUseDialogTopLayer() {
    return Boolean(this.el && !this.deprecatedDisableTopLayer && 'showModal' in this.el && 'close' in this.el);
  }

  private get shouldHideCurrentDialogHost() {
    return Boolean(this.el && !this.deprecatedDisableTopLayer && 'showModal' in this.el && 'close' in this.el);
  }

  private get shouldHideCurrentPopoverHost() {
    return Boolean(
      this.el &&
      !this.deprecatedDisableTopLayer &&
      this.el.getAttribute('popover') === 'manual' &&
      supportsPopoverApi(this.el),
    );
  }

  @Watch('open')
  openWatcher(open: boolean) {
    if (open) {
      this.show();
    } else {
      this.hide();
    }
    this.syncEscapeHandling();
  }

  @Watch('mode')
  modeWatcher() {
    this.syncEscapeHandling();
    if (this.open) {
      this.hide();
    } else {
      this.applyFallbackZIndex();
    }
  }

  @Watch('zIndex')
  @Watch('deprecatedDisableTopLayer')
  fallbackZIndexWatcher() {
    this.applyFallbackZIndex();
  }

  @Watch('captureEscape')
  @Watch('closeByEscape')
  escapeWatcher() {
    this.syncEscapeHandling();
  }

  private syncEscapeHandling() {
    const shouldHandleEscape = this.open && (this.captureEscape || this.closeByEscape);

    topModalIdStack.remove(this.modalId);
    this.cleanupKeydownListener?.();
    this.cleanupKeydownListener = undefined;

    if (!shouldHandleEscape) {
      return;
    }

    topModalIdStack.push(this.modalId);
    const handler = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || topModalIdStack.last() !== this.modalId) {
        return;
      }

      const shouldConsume = this.captureEscape || this.closeByEscape;
      if (!shouldConsume) {
        return;
      }

      if (this.closeByEscape) {
        this.ksRequestClose.emit('escape');
      }

      event.preventDefault();
      event.stopPropagation();
    };

    document.addEventListener('keydown', handler, { capture: true });
    this.cleanupKeydownListener = () => document.removeEventListener('keydown', handler, { capture: true });
  }

  private applyFallbackZIndex() {
    if (!this.el || this.mode !== 'modeless' || this.shouldUseNativePopoverApi) {
      return;
    }

    this.el.style.zIndex =
      this.zIndex !== undefined ? String(this.zIndex) : this.el.style.zIndex || String(allocateFallbackZIndex());
  }

  private clearFallbackZIndex() {
    if (!this.el || this.shouldHideCurrentPopoverHost || this.zIndex !== undefined) {
      return;
    }

    this.el.style.zIndex = '';
  }

  private show() {
    if (this.shouldLockScroll && !this.hasScrollLock) {
      globalScrollLock.acquire();
      this.hasScrollLock = true;
    }
    this.applyFallbackZIndex();

    if (this.mode === 'modal') {
      if (this.isPresented) {
        return;
      }

      if (this.shouldUseDialogTopLayer && !(this.el as HTMLDialogElement).open) {
        (this.el as HTMLDialogElement).showModal();
      }
      this.isPresented = true;
      return;
    }

    if (this.shouldUseNativePopoverApi) {
      if (this.isPresented) {
        return;
      }

      try {
        this.el?.showPopover();
      } catch {
        // ignore InvalidStateError if the popover is already shown
      }
      this.isPresented = true;
      return;
    }

    this.isPresented = true;
  }

  private hide() {
    if (this.shouldHideCurrentDialogHost && (this.el as HTMLDialogElement).open) {
      (this.el as HTMLDialogElement).close();
    } else if (this.shouldHideCurrentPopoverHost) {
      try {
        this.el?.hidePopover();
      } catch {
        // ignore InvalidStateError if the popover is already hidden
      }
    }

    this.clearFallbackZIndex();
    if (this.hasScrollLock) {
      globalScrollLock.release();
      this.hasScrollLock = false;
    }
    this.isPresented = false;
  }

  connectedCallback() {
    this.syncEscapeHandling();
  }

  componentDidRender() {
    if (this.open) {
      if (!this.isPresented) {
        this.show();
      }
      return;
    }

    if (this.isPresented || this.hasScrollLock) {
      this.hide();
    } else {
      this.applyFallbackZIndex();
    }
  }

  disconnectedCallback() {
    this.el &&
      whenNotReconnected(this.el, () => {
        topModalIdStack.remove(this.modalId);
        this.hide();
        this.cleanupKeydownListener?.();
        this.cleanupKeydownListener = undefined;
      });
  }

  private preventDialogNativeCancel = (event: Event) => {
    if (!this.shouldUseDialogTopLayer) return;

    if (event.cancelable) {
      event.preventDefault();
    } else {
      requestAnimationFrame(() => {
        if (this.shouldUseDialogTopLayer && !(this.el as HTMLDialogElement).open) {
          (this.el as HTMLDialogElement).showModal();
        }
      });
    }
  };

  private renderAsModal() {
    if (this.deprecatedDisableTopLayer) {
      return (
        <div
          {...topLayerSurfaceAttrs}
          ref={this.setBaseRef}
          class={prefix}
          part="base"
          style={{
            display: this.open ? 'flex' : 'none',
            zIndex: this.zIndex !== undefined ? String(this.zIndex) : '',
          }}
        >
          <slot />
        </div>
      );
    }

    return (
      <dialog
        {...topLayerSurfaceAttrs}
        ref={this.setBaseRef}
        class={prefix}
        part="base"
        onCancel={this.preventDialogNativeCancel}
      >
        <slot />
      </dialog>
    );
  }

  private renderAsModeless() {
    if (this.deprecatedDisableTopLayer) {
      return (
        <div
          {...topLayerSurfaceAttrs}
          ref={this.setBaseRef}
          class={prefix}
          part="base"
          style={{
            display: this.open ? 'flex' : 'none',
            zIndex: this.zIndex !== undefined ? String(this.zIndex) : '',
          }}
        >
          <slot />
        </div>
      );
    }

    return (
      <div
        {...topLayerSurfaceAttrs}
        ref={(el) => {
          this.setBaseRef(el);
          this.applyFallbackZIndex();
        }}
        class={prefix}
        part="base"
        popover="manual"
        style={{
          display: this.open ? 'flex' : 'none',
        }}
      >
        <slot />
      </div>
    );
  }

  render() {
    return <Host class="KsOverlay">{this.mode === 'modal' ? this.renderAsModal() : this.renderAsModeless()}</Host>;
  }
}
