import { isUndefined } from 'lodash-es';

export const assignment = <T extends HTMLElement, E>(el: T, key: string, value: E) => {
  if (!isUndefined(value)) {
    // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
    el[key] = value;
  }
};

export const whenNotReconnected = (el: HTMLElement, callback: () => void) => {
  Promise.resolve().then(() => {
    if (!el.isConnected) {
      callback();
    }
  });
};

export const traverseDOMTree = (el: HTMLElement, callback: (el: HTMLElement) => void) => {
  callback(el);
  for (const child of el.children) {
    traverseDOMTree(child as HTMLElement, callback);
  }
};
